import axios from 'axios';

// Check if the backend URL is configured
const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL;

if (!backendUrl) {
  console.error(
    "Backend URL not configured. Please set NEXT_PUBLIC_BACKEND_URL in your .env file."
  );
}

// Create an axios instance with better defaults
const api = axios.create({
  baseURL: backendUrl || 'http://localhost:8000', // Fallback to localhost if not set
  timeout: 15000, // 15 seconds timeout
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
  },
  withCredentials: true,
});

// Add request interceptor for handling auth and debugging
api.interceptors.request.use(
  (config) => {
    // Log the request in development
    if (process.env.NODE_ENV === 'development') {
      console.log(`API Request: ${config.method?.toUpperCase()} ${config.baseURL}${config.url}`);
    }
    
    if (typeof window !== "undefined") {
      const accessToken = localStorage.getItem("access_token");
      if (accessToken) {
        config.headers.Authorization = `Bearer ${accessToken}`;
      }
    }
    
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Add response interceptor for common error handling
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    // Handle network errors with clear messages
    if (error.message === 'Network Error') {
      console.error(
        'Network Error: Cannot connect to the backend server. ' +
        'Please check if your backend is running and the NEXT_PUBLIC_BACKEND_URL is correct.'
      );
    }
    
    // Handle timeout
    if (error.code === 'ECONNABORTED') {
      console.error('Request timeout: The server took too long to respond.');
    }
    
    // Log full error details in development
    if (process.env.NODE_ENV === 'development') {
      console.error('API Error Details:', {
        message: error.message,
        code: error.code,
        status: error.response?.status,
        data: error.response?.data,
        url: error.config?.url,
      });
    }
    
    return Promise.reject(error);
  }
);

export default api;
